insert into public.providers (
  source_profile_id, business_name, category_id, subcategory, description,
  base_city, base_postcode, street_address, service_areas, phone, whatsapp,
  avg_rating, review_count, source_url, website, google_place_id, data_notes,
  is_verified, is_claimed, verification_status
)
select
  s.source_profile_id,
  s.business_name,
  c.id,
  s.subcategory,
  s.description,
  s.base_city,
  s.base_postcode,
  s.street_address,
  array[s.base_city],
  s.phone,
  s.phone,
  s.avg_rating,
  s.review_count,
  s.source_url,
  s.website,
  s.google_place_id,
  replace(s.data_notes, 'ChodhiQ', 'ChodhiQ'),
  false,
  false,
  'unverified'
from source s
join public.categories c on c.slug = s.category_slug
where not exists (
  select 1 from public.providers p where p.source_profile_id = s.source_profile_id
)
and not exists (
  select 1 from public.providers p
  where s.google_place_id is not null and p.google_place_id = s.google_place_id
)
and not exists (
  select 1 from public.providers p
  where lower(btrim(p.business_name)) = lower(btrim(s.business_name))
    and coalesce(upper(regexp_replace(p.base_postcode, '\s+', '', 'g')), '') =
        coalesce(upper(regexp_replace(s.base_postcode, '\s+', '', 'g')), '')
)
on conflict do nothing;
